insert into public.settings(id,data) values(1,'{"headline":"Your Partner in IT Solutions, Repairs & Custom Development.","banner":"","phone":"+63 963 310 2486","email":"twotech0128@gmail.com","address":"Purok 4, Brgy. Sta. Maria, Filinvest Rd, Santo Tomas, Batangas, Philippines","hours":"9:00 AM–8:00 PM","facebook":"https://www.facebook.com/Engr.TwoTECH","delivery_fee":150,"payment_instructions":"Contact Two Tech for verified bank or GCash transfer instructions before sending payment.","founder_bio":"Kurt Decena is a Computer Engineering graduate with IT support and software development experience.","low_stock_threshold":5,"services":[{"id":"dev","title":"Programming & Software Development","description":"Software built around how your business actually works.","visible":true,"starting_price":null,"price_label":"From","items":[{"name":"Website development","price":null},{"name":"Business systems & desktop apps","price":null},{"name":"Custom Python applications","price":null},{"name":"API integration","price":null},{"name":"Bug fixing & system maintenance","price":null}],"modes":[]},{"id":"auto","title":"Automation & AI","description":"Remove repetitive work and add smart features.","visible":true,"starting_price":null,"price_label":"From","items":[{"name":"Excel/VBA automation","price":null},{"name":"Workflow automation","price":null},{"name":"Chatbot development","price":null},{"name":"Image processing & object detection","price":null}],"modes":[]},{"id":"emb","title":"Embedded Systems & IoT","description":"Hardware and firmware built to sense and respond.","visible":true,"starting_price":null,"price_label":"From","items":[{"name":"Arduino & ESP32 programming","price":null},{"name":"Sensor integration","price":null},{"name":"Monitoring systems","price":null},{"name":"Smart device development","price":null},{"name":"Custom embedded projects","price":null}],"modes":[]},{"id":"setup","title":"Computer Setup & Upgrades","description":"Build it right or upgrade what you have.","visible":true,"starting_price":500,"price_label":"From","items":[{"name":"Custom PC assembly","price":null},{"name":"Parts compatibility assessment","price":null},{"name":"RAM & SSD upgrades","price":null},{"name":"GPU installation","price":null},{"name":"Operating system & driver setup","price":null}],"modes":["Drop-off","Onsite"]},{"id":"repair","title":"Computer Repair & Troubleshooting","description":"Careful diagnosis before any parts are replaced.","visible":true,"starting_price":300,"price_label":"Diagnosis from","items":[{"name":"No-display & boot issue diagnosis","price":null},{"name":"Overheating & sudden shutdown","price":null},{"name":"Slow computer troubleshooting","price":null},{"name":"Hardware & software diagnosis","price":null}],"modes":["Drop-off","Onsite"]},{"id":"soft","title":"Formatting & Software","description":"Clean installs, with your files backed up first.","visible":true,"starting_price":500,"price_label":"From","items":[{"name":"Windows installation/reinstallation","price":null},{"name":"Computer formatting","price":null},{"name":"Driver installation","price":null},{"name":"Licensed software setup","price":null},{"name":"Malware removal","price":null},{"name":"Data backup before formatting","price":null}],"modes":["Drop-off","Onsite","Remote"]},{"id":"clean","title":"Cleaning & Cooling Maintenance","description":"Lower temperatures and quieter fans. GPU service depends on the card model and condition, and is not suitable for every card.","visible":true,"starting_price":400,"price_label":"From","items":[{"name":"System unit deep cleaning","price":null},{"name":"CPU thermal paste replacement","price":null},{"name":"GPU cleaning & thermal paste","price":null},{"name":"Thermal pad inspection/replacement where appropriate","price":null}],"modes":["Drop-off","Onsite"]},{"id":"net","title":"Network & IT Support","description":"Stable Wi-Fi, shared files, and printers that print.","visible":true,"starting_price":500,"price_label":"From","items":[{"name":"Router & Wi-Fi setup","price":null},{"name":"LAN troubleshooting","price":null},{"name":"Printer setup","price":null},{"name":"File sharing setup","price":null},{"name":"Remote & onsite technical support","price":null}],"modes":["Onsite","Remote"]}],"booking_times":["9:00 AM","11:00 AM","1:00 PM","3:00 PM","5:00 PM"],"quote_categories":["Website","Desktop Application","Automation","AI/Image Processing","Embedded Systems/IoT","Other"],"quote_budgets":["Under ₱10,000","₱10,000 – ₱30,000","₱30,000 – ₱100,000","Above ₱100,000","Not sure yet"],"maps":"https://maps.app.goo.gl/KLWRCZbpFzx4qBjE8","founder_name":"Kurt Decena","service_area":"Nearby areas subject to availability.","business_intro":"Two Tech (Computer Engrs'' Repair Services) is a Philippines-based business offering computer parts, repair and maintenance, software development, automation, and embedded systems projects.","policies":{"privacy":{"title":"Privacy Policy","intro":"Owner review required: this is a draft describing the current website. The owner must confirm retention periods, request handling and provider arrangements before publishing the final policy.","sections":[["Information we collect","Orders collect your name, email, phone number, delivery choice and address when delivery is requested. Bookings also collect device information, the reported problem, requested schedule, service mode and onsite address when applicable. Project inquiries collect requirements, hardware needs, budget range, optional target date and reference link. Contact messages collect your name, email and message. Please avoid sending passwords or unnecessary sensitive information."],["How information is used","Two Tech uses your information to respond, review requirements, arrange requested services, prepare quotations, fulfil orders and verify manual transfers. We do not collect card numbers or card security codes. Do not send card details through any form."],["Providers and storage","Netlify hosts the website and API and receives a copy of submitted orders and inquiries through Netlify Forms for owner notifications. Neon stores the records shown in the administrator Inbox, and Cloudinary stores product images. The owner may receive these submission details by email through Netlify notifications. The owner must confirm retention and access arrangements for these copies, and any additional parties involved in delivery."],["Browser storage and access","Your browser stores product IDs and quantities for your cart and a short submission throttle. Administrator access uses a secure session cookie. Access to order and inquiry records is restricted to authenticated administrators."],["Retention and requests","Owner to confirm: how long orders, bookings, quotations, messages and security records are retained, and how deletion or correction requests are handled. Contact Two Tech using the details below to ask about your information."],["Changes to this notice","The owner should review and update this notice when the website, providers or data-handling practices change."]]},"terms":{"title":"Orders & Returns","intro":"Owner review required: this draft explains the current ordering process. The owner must complete the policy items marked below; they are not promises about unconfirmed services or return rights.","sections":[["Order requests and prices","Submitting checkout creates an order received reference. It does not mean the order is paid or confirmed for fulfilment. The server checks product availability, stock, current prices and the configured delivery fee when the order is submitted. Two Tech will contact you regarding the next steps."],["Payment methods","Payment is Cash on Pickup/Delivery or manual Bank/GCash transfer. No card payment is collected or processed on this website. For a transfer, follow the current payment instructions shown at checkout. The administrator marks payment only after verifying it."],["Pickup, delivery and reservations","Pickup is free; the configured delivery fee is displayed before submission. Owner to confirm: delivery coverage, lead times, reservation duration, payment deadline and arrangements for missed pickup or unavailable customers."],["Repairs and project quotations","Bookings are schedule requests until Two Tech confirms them. Repair estimates depend on inspection, device condition, parts and agreed scope. Project requirements are reviewed before a quotation is provided. No work or price commitment is implied solely by submitting a request."],["Cancellations, returns and refunds","Owner to confirm: cancellation procedure, return eligibility, time limits, condition requirements, proof of purchase, shipping responsibilities and refund process. Contact Two Tech before returning any item. This draft does not establish a warranty or return guarantee."],["Device handling and software","Owner to confirm: repair authorization, data-backup responsibilities, device collection, parts handling and any applicable service terms. Software setup requires appropriately licensed software."]]}}}'::jsonb) on conflict(id) do nothing;
